const cds = require('@sap/cds');
module.exports = cds.service.impl(async function(srv) {
  this.on('CREATE', 'Employees', async (req) => {
    const data = req.data;
    return await INSERT.into('Employees').entries(data);
  });
  this.on('DELETE', 'Employees', async (req) => {
    await DELETE.from('Employees').where({ ID: req.params[0] });
  });
  this.on('exportEmployees', async (req) => {
    const rows = await SELECT.from('Employees');
    return rows;
  });
});

sap.ui.define([], function() {
  return Controller.extend('Employees', {
    onSave: function() { this.getView().getModel().submitChanges(); },
    onExport: function() { this.getView().getModel().callFunction('/exportEmployees'); }
  });
});
